import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t_str = next(iterator)
        t = int(t_str)
    except StopIteration:
        return

    for _ in range(t):
        try:
            a = next(iterator)
            b = next(iterator)
        except StopIteration:
            break

        set_a = set(a)
        set_b = set(b)

        common = False
        for char in set_a:
            if char in set_b:
                common = True
                break

        if common:
            print("Yes")
        else:
            print("No")

if __name__ == "__main__":
    solve()
